using System;using System.IO;using System.Reflection;using System.Windows.Forms;using Microsoft.Win32;
class Installer { [STAThread] static void Main(){var dir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"DruryIT Support");Directory.CreateDirectory(dir);Write("DruryITSupport.exe",dir);Write("appsettings.json",dir);var exe=Path.Combine(dir,"DruryITSupport.exe");using(var key=Registry.CurrentUser.CreateSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run"))key.SetValue("DruryIT Support","\""+exe+"\"");File.WriteAllText(Path.Combine(dir,"Uninstall.ps1"),"Remove-ItemProperty -Path 'HKCU:\\Software\\Microsoft\\Windows\\CurrentVersion\\Run' -Name 'DruryIT Support' -ErrorAction SilentlyContinue\r\nRemove-Item '"+dir.Replace("'","''")+"' -Recurse -Force");var shell=Type.GetTypeFromProgID("WScript.Shell");dynamic w=Activator.CreateInstance(shell);string desktop=Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory);dynamic shortcut=w.CreateShortcut(Path.Combine(desktop,"DruryIT Support.lnk"));shortcut.TargetPath=exe;shortcut.WorkingDirectory=dir;shortcut.Save();MessageBox.Show("DruryIT Support has been installed. It will appear by the clock and start when you sign in.","DruryIT Support");System.Diagnostics.Process.Start(exe,"--open");}static void Write(string name,string dir){using(var s=Assembly.GetExecutingAssembly().GetManifestResourceStream(name))using(var f=File.Create(Path.Combine(dir,name))){s.CopyTo(f);}}}
